// TokenExchangeOAuthSettings OAuth-specific token-exchange behavior, such as how scopes are handled, with optional inheritance from domain defaults.
type TokenExchangeOAuthSettings struct {
	// ClaimMappings Claims copied from the validated subject or actor token onto the issued token. A claim that is absent from its source token is skipped.
	ClaimMappings *[]TokenExchangeClaimMapping `json:"claimMappings,omitempty"`

	// Inherited Whether these settings are inherited from the domain defaults rather than defined here.
	Inherited *bool `json:"inherited,omitempty"`

	// ScopeHandling How scopes are handled when issuing the exchanged token. DOWNSCOPING restricts the issued token to a subset of the original scopes.
	ScopeHandling *TokenExchangeOAuthSettingsScopeHandling `json:"scopeHandling,omitempty"`
}

// TokenExchangeOAuthSettingsScopeHandling How scopes are handled when issuing the exchanged token. DOWNSCOPING restricts the issued token to a subset of the original scopes.
type TokenExchangeOAuthSettingsScopeHandling string

// TokenExchangeSettings OAuth 2.0 Token Exchange (RFC 8693) configuration for the domain, covering impersonation and delegation.
type TokenExchangeSettings struct {
	// AllowDelegation Whether delegation is allowed, where an actor acts on behalf of the subject and an "act" claim is added to the issued token. At least one of allowImpersonation or allowDelegation must be enabled.
	AllowDelegation *bool `json:"allowDelegation,omitempty"`

	// AllowImpersonation Whether impersonation is allowed, where the issued token represents the subject directly. At least one of allowImpersonation or allowDelegation must be enabled.
	AllowImpersonation *bool `json:"allowImpersonation,omitempty"`

	// AllowedActorTokenTypes Token types accepted as the actor token when delegating.
	//
	// Example: ["urn:ietf:params:oauth:token-type:access_token","urn:ietf:params:oauth:token-type:id_token"]
	AllowedActorTokenTypes *[]string `json:"allowedActorTokenTypes,omitempty"`

	// AllowedRequestedTokenTypes Token types that may be requested as the result of an exchange.
	//
	// Example: ["urn:ietf:params:oauth:token-type:access_token","urn:ietf:params:oauth:token-type:id_token"]
	AllowedRequestedTokenTypes *[]string `json:"allowedRequestedTokenTypes,omitempty"`

	// AllowedSubjectTokenTypes Token types accepted as the subject token in an exchange.
	//
	// Example: ["urn:ietf:params:oauth:token-type:access_token","urn:ietf:params:oauth:token-type:id_token"]
	AllowedSubjectTokenTypes *[]string `json:"allowedSubjectTokenTypes,omitempty"`

	// Enabled Whether token exchange is enabled for the domain.
	Enabled *bool `json:"enabled,omitempty"`

	// MaxDelegationDepth Maximum depth of the delegation chain (nested "act" claims). Clamped to the range 1–100.
	MaxDelegationDepth *int32 `json:"maxDelegationDepth,omitempty"`

	// TokenExchangeOAuthSettings OAuth-specific token-exchange behavior, such as how scopes are handled, with optional inheritance from domain defaults.
	TokenExchangeOAuthSettings *TokenExchangeOAuthSettings `json:"tokenExchangeOAuthSettings,omitempty"`

	// TrustedIssuers External issuers whose JWTs may be accepted as subject or actor tokens. When unset, only domain-issued tokens are accepted.
	TrustedIssuers *[]TrustedIssuer `json:"trustedIssuers,omitempty"`
}

// TrustedIssuer An external token issuer whose JWTs are accepted as subject or actor tokens during token exchange, validated with the configured key material.
type TrustedIssuer struct {
	// Certificate PEM-encoded X.509 certificate. Required when keyResolutionMethod is PEM.
	Certificate *string `json:"certificate,omitempty"`

	// Issuer Expected value of the "iss" claim in the external JWT.
	//
	// Example: https://issuer.example.com
	Issuer *string `json:"issuer,omitempty"`

	// JwksUri JWKS endpoint URL. Required when keyResolutionMethod is JWKS_URL.
	//
	// Example: https://issuer.example.com/.well-known/jwks.json
	JwksUri *string `json:"jwksUri,omitempty"`

	// KeyResolutionMethod How the issuer's signing key is resolved. JWKS_URL fetches keys from a JWKS endpoint; PEM uses an inline X.509 certificate.
	KeyResolutionMethod *TrustedIssuerKeyResolutionMethod `json:"keyResolutionMethod,omitempty"`

	// ScopeMappings One-to-one mapping from external scope to domain scope. Unmapped issuer scopes are dropped (fail-closed).
	ScopeMappings *map[string]string `json:"scopeMappings,omitempty"`

	// UserBindingCriteria Criteria used to locate a domain user when user binding is enabled. All criteria are combined with AND.
	UserBindingCriteria *[]UserBindingCriterion `json:"userBindingCriteria,omitempty"`

	// UserBindingEnabled Whether the external JWT subject is resolved to a single domain user using the user binding criteria. When false, a virtual user is built from the token claims only.
	UserBindingEnabled *bool `json:"userBindingEnabled,omitempty"`
}

// TrustedIssuerKeyResolutionMethod How the issuer's signing key is resolved. JWKS_URL fetches keys from a JWKS endpoint; PEM uses an inline X.509 certificate.
type TrustedIssuerKeyResolutionMethod string

