// WebAuthnSettings WebAuthn (FIDO2) relying-party configuration governing passwordless and multi-factor authentication for the domain.
type WebAuthnSettings struct {
	// AttestationConveyancePreference Relying-party preference for attestation conveyance during credential creation. NONE requests no attestation, INDIRECT allows anonymized attestation, and DIRECT requests the authenticator's attestation statement.
	AttestationConveyancePreference *WebAuthnSettingsAttestationConveyancePreference `json:"attestationConveyancePreference,omitempty"`

	// AuthenticatorAttachment Preferred authenticator attachment. PLATFORM selects authenticators bound to the device (such as a fingerprint reader); CROSS_PLATFORM selects roaming authenticators (such as a security key).
	AuthenticatorAttachment *WebAuthnSettingsAuthenticatorAttachment `json:"authenticatorAttachment,omitempty"`

	// Certificates Trusted device-attestation X.509 certificates, keyed by name.
	Certificates *map[string]string `json:"certificates,omitempty"`

	// EnforceAuthenticatorIntegrity Whether to periodically re-verify that registered authenticators remain valid against the FIDO2 Metadata Service.
	EnforceAuthenticatorIntegrity *bool `json:"enforceAuthenticatorIntegrity,omitempty"`

	// EnforceAuthenticatorIntegrityMaxAge Maximum elapsed time, in seconds, since an authenticator was last verified before it is re-checked on the next passwordless login.
	EnforceAuthenticatorIntegrityMaxAge *int32 `json:"enforceAuthenticatorIntegrityMaxAge,omitempty"`

	// ForceRegistration Whether to reject registration of a credential already registered to a different user.
	ForceRegistration *bool `json:"forceRegistration,omitempty"`

	// Origin Relying-party origin; must match the browser's window.location.origin during registration and authentication ceremonies.
	//
	// Example: https://auth.example.com
	Origin *string `json:"origin,omitempty"`

	// RelyingPartyId Relying-party identifier: a domain string that scopes credentials to this entity. A credential can only be used with the relying party it was registered against.
	//
	// Example: auth.example.com
	RelyingPartyId *string `json:"relyingPartyId,omitempty"`

	// RelyingPartyName Human-readable relying-party name shown to users during ceremonies.
	//
	// Example: Example Inc.
	RelyingPartyName *string `json:"relyingPartyName,omitempty"`

	// RequireResidentKey Whether the authenticator must create a client-side resident (discoverable) credential.
	RequireResidentKey *bool `json:"requireResidentKey,omitempty"`

	// UserVerification Relying-party requirement regarding user verification during a ceremony. REQUIRED enforces verification, PREFERRED requests it when available, and DISCOURAGED avoids it.
	UserVerification *WebAuthnSettingsUserVerification `json:"userVerification,omitempty"`
}

// WebAuthnSettingsAttestationConveyancePreference Relying-party preference for attestation conveyance during credential creation. NONE requests no attestation, INDIRECT allows anonymized attestation, and DIRECT requests the authenticator's attestation statement.
type WebAuthnSettingsAttestationConveyancePreference string

// WebAuthnSettingsAuthenticatorAttachment Preferred authenticator attachment. PLATFORM selects authenticators bound to the device (such as a fingerprint reader); CROSS_PLATFORM selects roaming authenticators (such as a security key).
